import numpy as np


def generate_parameters(n):
    parameter_set = []
    for i in range(n):
        params = {
            "seed": i * 10 + 7,
            "dimension": (i % 5) + 2,
            "pos_range": 50 * (i + 1),
            "int_range": 5 * (i + 1),
            "size": 500,
            "no_theoretical_distributions": (i % 4) + 2,
            "point": tuple(0.1 * (j + 1) for j in range((i % 5) + 2)),
        }
        parameter_set.append(params)
    return parameter_set

